// Crunchyroll service helper.
//
// Crunchyroll's playback flow needs an opaque per-stream token in the
// `x-cr-video-token` header. Every recent agent session has gotten stuck
// at the same wall: the playback APIs return {"error":"Unauthorized",
// "reason":"missing_token"} because that token is generated by a
// dedicated auth dance, not by sending session cookies.
//
// The flow is documented (devine-cr / cr-py code mirrors it):
//
//   1. POST /auth/v1/token         body=grant_type=etp_rt_cookie
//                                  Basic auth = static web client id
//      → { access_token, expires_in, ... }
//
//   2. GET  /playback/v3/<id>/web/chrome/play
//      headers: Authorization: Bearer <access_token>
//      → { url: <manifest mpd url>, token: <x-cr-video-token>,
//          assetId, playbackGuid, audioLocale, hardSubs, ... }
//
//   3. The manifest URL from step 2 already encodes playbackGuid +
//      accountId. Fetch it with header `x-cr-video-token: <token>`
//      → DASH MPD with <cenc:pssh>
//
//   4. Widevine license POST hits /license/v1/license/widevine with
//      `x-cr-video-token: <token>` and `Authorization: Bearer ...`
//      (the same access_token).
//
// This whole chain runs INSIDE the logged-in page so the etp_rt cookie
// (which is HttpOnly) and Cloudflare's __cf_bm are sent automatically.
//
// What this tool does NOT do:
//   - Decrypt anything. You still need a .wvd device file for that.
//     The point of this tool is to hand the agent the inputs it needs
//     (manifest url, license url, x-cr-video-token, pssh) so the rest
//     of the pipeline (widevine_keys + m3u8dl_download) can run.
//
// Public client id is the same one Crunchyroll's web player uses; it
// is committed to their public JS bundle (search for `noaihdevm_`).
// Treat it as a constant of the service, not a secret.
const _CR_WEB_CLIENT_ID = 'noaihdevm_6iyg0a8l0q';

(() => {
  'use strict';
  const { T, STR, NUM, OBJ, activeTab } = window.KyotoTR;

  function _videoIdFromUrl(url) {
    // /watch/<id>/<slug> — id is GE-prefixed alphanumeric.
    const m = String(url || '').match(/\/watch\/([A-Z0-9]+)/i);
    return m ? m[1] : null;
  }

  // Runs the whole auth dance in the page's main world so HttpOnly
  // cookies (etp_rt, __cf_bm) are sent automatically. Returns
  // { ok, manifest_url, license_url, video_token, bearer_token, pssh,
  //   key_ids, mpd_xml, asset_id, playback_guid } on success.
  async function _runCrFlow(tabId, videoId) {
    const { scrip } = window.KyotoTR;
    const clientId = _CR_WEB_CLIENT_ID;
    const result = await scrip(tabId, async function (videoId, clientId) {
      function _b64(s) { return btoa(unescape(encodeURIComponent(s))); }
      const out = {
        manifest_url: null, license_url: 'https://www.crunchyroll.com/license/v1/license/widevine',
        video_token: null, bearer_token: null, pssh: null, key_ids: [],
        mpd_xml: null, asset_id: null, playback_guid: null, steps: []
      };
      try {
        // 1. Get a Bearer access_token using the etp_rt cookie grant.
        const authResp = await fetch('https://www.crunchyroll.com/auth/v1/token', {
          method: 'POST',
          headers: {
            'Authorization': 'Basic ' + _b64(clientId + ':'),
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          body: 'grant_type=etp_rt_cookie',
          credentials: 'include',
        });
        out.steps.push({ step: 'auth/v1/token', status: authResp.status });
        if (!authResp.ok) {
          const text = await authResp.text().catch(() => '');
          return { ...out, error: `auth/v1/token returned ${authResp.status}: ${text.slice(0, 300)}`,
            hint: authResp.status === 401
              ? 'etp_rt cookie missing or expired — user needs to sign in to Crunchyroll in this browser session.'
              : 'unexpected auth response — Crunchyroll may have changed the protocol.' };
        }
        const auth = await authResp.json();
        out.bearer_token = auth.access_token;
        if (!auth.access_token) return { ...out, error: 'auth response had no access_token', authResp: auth };

        // 2. Get stream info (manifest URL + x-cr-video-token).
        const playResp = await fetch(
          'https://www.crunchyroll.com/playback/v3/' + videoId + '/web/chrome/play',
          { headers: { 'Authorization': 'Bearer ' + auth.access_token }, credentials: 'include' }
        );
        out.steps.push({ step: 'playback/v3/play', status: playResp.status });
        if (!playResp.ok) {
          const text = await playResp.text().catch(() => '');
          return { ...out, error: `playback/v3 returned ${playResp.status}: ${text.slice(0, 300)}`,
            hint: 'Verify you have an active Crunchyroll Premium subscription and the title is available in your region.' };
        }
        const play = await playResp.json();
        out.video_token = play.token;
        out.asset_id = play.assetId;
        out.playback_guid = play.playbackGuid || play.playback_guid;
        out.manifest_url = play.url;

        // 3. Fetch the manifest XML with the video token header.
        if (out.manifest_url && out.video_token) {
          const mpdResp = await fetch(out.manifest_url, {
            headers: { 'x-cr-video-token': out.video_token },
            credentials: 'include',
          });
          out.steps.push({ step: 'manifest.mpd', status: mpdResp.status });
          if (mpdResp.ok) {
            const xml = await mpdResp.text();
            out.mpd_xml = xml;
            // Extract first PSSH and any key IDs (cenc:default_KID).
            const psshMatch = xml.match(/<cenc:pssh[^>]*>([^<]+)<\/cenc:pssh>/i);
            if (psshMatch) out.pssh = psshMatch[1].trim();
            const kidRe = /cenc:default_KID="([0-9a-fA-F-]{36})"/g;
            const kids = new Set();
            let m; while ((m = kidRe.exec(xml))) kids.add(m[1].toLowerCase());
            out.key_ids = [...kids];
          }
        }
        return { ok: true, ...out };
      } catch (e) {
        return { ...out, error: 'in-page exception: ' + (e?.message || String(e)) };
      }
    }, [videoId, clientId], 'MAIN');
    return result;
  }

  // ──────── TOOLS ────────

  T({
    name: 'cr_get_stream_info',
    group: 'media',
    description:
      'Run Crunchyroll\'s authentication flow inside the active (logged-in) tab and return everything needed to download the current video. ' +
      'Hits /auth/v1/token with the etp_rt cookie to get a Bearer access_token, then /playback/v3/<id>/web/chrome/play to get the manifest URL + x-cr-video-token, then fetches the MPD and extracts PSSH + key IDs. ' +
      'Pass `videoId` to override; otherwise auto-detects from the active tab URL (/watch/<id>/...). ' +
      'Returns { ok, manifest_url, license_url, video_token, bearer_token, pssh, key_ids, mpd_xml, asset_id, playback_guid, steps } on success. ' +
      'Use the returned `video_token` + `bearer_token` as headers for `widevine_keys` (Authorization: Bearer ..., x-cr-video-token: ...), and the `manifest_url` + cookies for `m3u8dl_download`. ' +
      'NOTE: requires the user to be signed in to Crunchyroll in this browser AND have a Premium subscription for the title.',
    parameters: OBJ({ videoId: STR, tabId: NUM }),
    handler: async ({ videoId, tabId } = {}) => {
      const t = tabId != null && tabId > 0
        ? await chrome.tabs.get(tabId).catch(() => null)
        : await activeTab();
      if (!t?.id) return { error: 'no active tab' };
      const id = videoId || _videoIdFromUrl(t.url) || _videoIdFromUrl(t.pendingUrl);
      if (!id) {
        return {
          error: 'could not infer videoId',
          tabUrl: t.url,
          hint: 'Pass `videoId` explicitly (Crunchyroll IDs look like GE00367923JAJP) OR navigate to the /watch/ page first.'
        };
      }
      const r = await _runCrFlow(t.id, id);
      if (!r) return { error: 'in-page script returned nothing — page may not be on crunchyroll.com' };
      if (r.error) return r;  // already has steps[] for debugging
      return r;
    }
  });
})();
